"""Whole public rbtree header: membership, links, cached and search helpers."""
def register(topic, q, detail):
    def lesson(title, symbol, why, principle, use, reading, qa, cards):
        topic(title, '라이브러리·알고리즘', 'include/linux/rbtree.h', symbol,
              why, principle, use, reading, *(q(*x) for x in qa),
              details=[detail(*x) for x in cards])

    lesson('레드블랙 빈 표식·자기 주소와 안전한 객체 변환', 'RB_EMPTY_NODE',
        '노드가 연결되지 않았다는 표시와 빈 루트·NULL 포인터를 구분하는 방법을 배웁니다.',
        'RB_CLEAR_NODE는 부모·색 저장값에 노드 자신의 주소를 넣습니다. RB_EMPTY_NODE는 그 값이 자기 주소인지 비교합니다. RB_EMPTY_ROOT는 루트 포인터가 NULL인지 READ_ONCE로 읽습니다. rb_entry는 포함 객체로 변환하며 rb_entry_safe는 입력 포인터를 한 번 저장하고 NULL이면 NULL을 반환합니다.',
        '삭제 API가 빈 표식을 자동으로 넣는다고 가정하지 않습니다. 명시적으로 표식을 관리한 노드에서만 이 검사로 소속 여부를 판단합니다. NULL 노드와 자기 주소 표식은 다르며 동시 변경의 예약·수명 보호를 이 검사만으로 제공하지 않습니다.',
        'RB_CLEAR_NODE, RB_EMPTY_NODE, rb_entry_safe의 임시 변수와 typeof를 읽으세요.',
        [('RB_EMPTY_NODE가 참이 되는 저장 상태는?', '부모·색 값이 노드 자신의 주소인 상태다', '왼쪽 자식이 NULL인 모든 잎이다', '잎도 정상 삽입된 노드일 수 있습니다. 빈 표식은 자식 수가 아니라 자기 주소를 저장한 명시적 상태입니다.'),
         ('rb_entry_safe에 NULL을 주면?', 'NULL을 반환한다', '무조건 포함 객체 주소로 변환한다', '매크로는 입력을 임시 변수에 한 번 저장한 뒤 NULL 여부를 검사합니다. 일반 rb_entry와 다른 안전한 NULL 처리입니다.')],
        [('부모 접근', 'rb_parent는 부모·색 값의 낮은 비트를 제외해 포인터를 얻습니다. 빈 자기 주소 표식을 실제 트리 부모 관계로 해석하지 않습니다.'),
         ('단일 평가', 'rb_entry_safe의 임시 변수는 ptr 식의 반복 평가를 피합니다. GNU C statement expression과 typeof의 사용 이유를 함께 읽습니다.')])

    lesson('레드블랙 노드 연결·빨간 초기 상태와 RCU 공개', 'rb_link_node',
        '검색으로 찾은 빈 자식 자리에 새 노드를 연결하는 최소 동작을 배웁니다.',
        'rb_link_node는 부모 주소를 부모·색 필드에 저장해 색 0인 빨강 상태를 만듭니다. 왼쪽·오른쪽 자식을 NULL로 초기화하고 rb_link 위치에 새 노드를 씁니다. RCU 형태는 마지막 연결 공개를 rcu_assign_pointer로 수행합니다. 이 함수 자체에는 키 검색이나 균형 복구가 없습니다.',
        '정렬 기준으로 빈 연결 위치와 부모를 먼저 구한 뒤 연결하고 rb_insert_color 또는 확장 삽입을 호출합니다. 새 노드의 데이터 초기화도 공개 전에 완료합니다. RCU 연결이 writer 직렬화나 전체 삽입 원자성을 제공한다고 해석하지 않습니다.',
        '일반 대입과 rb_link_node_rcu의 마지막 공개를 비교하세요.',
        [('rb_link_node 직후 새 노드의 색은?', '빨강이다', '항상 검정이다', '정렬된 부모 주소만 저장하고 색 비트 0을 사용합니다. 이후 색 복구가 루트와 연속 빨강 조건을 처리합니다.'),
         ('rb_link_node만 호출하면 전체 삽입이 완료되는가?', '아니며 위치 검색과 색 복구 책임이 따로 있다', '모든 키와 균형을 자동으로 처리한다', '함수는 주어진 위치에 연결할 뿐입니다. 호출자는 검색 조건을 지키고 연결 뒤 균형 API를 실행해야 합니다.')],
        [('포인터의 포인터', 'rb_link는 부모의 rb_left·rb_right 또는 루트 포인터의 주소입니다. *rb_link=node로 같은 방식으로 여러 위치에 연결합니다.'),
         ('재삽입', '이미 연결된 동일 노드를 다시 연결하지 않습니다. 삭제·빈 표식·수명과 데이터 초기화는 호출 흐름에서 관리합니다.')])

    lesson('레드블랙 safe 후위 순회·다음 객체를 먼저 보관하기', 'rbtree_postorder_for_each_entry_safe',
        '현재 객체를 정리하면서 계속 순회할 수 있는 매크로의 정확한 범위를 배웁니다.',
        '첫 후위 노드를 포함 객체 pos로 바꿉니다. 반복 조건에서 다음 후위 노드를 미리 n에 저장한 뒤 본문을 실행합니다. 이후 pos=n으로 이동하므로 현재 pos의 메모리를 본문에서 무효화해도 다음 위치를 그 메모리에서 다시 구하지 않습니다. 자식보다 부모를 늦게 방문하는 후위 순서를 사용합니다.',
        '전체 트리 객체를 후위 순서로 해제하는 데 사용할 수 있습니다. rb_erase처럼 회전으로 구조 순서를 바꾸는 수정은 허용 범위가 아닙니다. 전체 해제 뒤 남은 루트 포인터도 초기화하여 해제된 노드를 다시 사용하지 않습니다.',
        '반복 조건의 n 계산이 본문보다 앞에 있는지 읽으세요.',
        [('다음 후위 위치는 언제 계산하는가?', '현재 본문을 실행하기 전에 계산한다', '현재 객체를 해제한 뒤 역참조해 계산한다', '매크로는 조건식에서 n을 저장합니다. 현재 객체를 정리한 뒤 그 객체를 다시 읽지 않고 pos=n으로 이동합니다.'),
         ('safe가 보장하지 않는 것은?', '회전으로 트리 순서를 바꾸며 모든 노드를 계속 방문하는 동작이다', '현재 객체를 본문에서 정리하는 동작이다', '원본은 재배치와 rb_erase의 균형 변경을 명시적으로 제외합니다. 저장된 다음 위치가 모든 구조 변경을 추적하는 것은 아닙니다.')],
        [('NULL 변환', '시작과 다음 위치는 rb_entry_safe를 사용해 순회 끝의 NULL을 안전하게 객체 NULL로 연결합니다.'),
         ('수거와 제거', '전체를 해제하는 후위 순회와 유효한 트리를 유지하며 한 항목씩 지우는 삭제 순회를 구분합니다. 후위 safe에 rb_erase를 추가하면 그 조건을 깨뜨릴 수 있습니다.')])

    lesson('레드블랙 최소 캐시·삽입·삭제·교체의 유지 책임', 'rb_erase_cached',
        '최소 원소를 즉시 읽기 위해 각 변경에서 추가 포인터를 유지하는 방법을 배웁니다.',
        'rb_first_cached는 rb_leftmost를 즉시 읽습니다. cached 삽입은 leftmost 인자가 참이면 새 노드를 저장하고 색을 복구합니다. cached 삭제는 현재 최소를 지우는 경우 rb_next로 새 최소를 저장하고 그 새 값을 반환합니다. 최소가 아니면 반환 NULL이며 마지막 최소를 지워 빈 트리가 되어도 NULL입니다. cached 교체는 victim이 최소이면 new로 바꾼 뒤 일반 교체합니다.',
        'cached 루트에는 cached 변경 API를 일관되게 사용합니다. 삽입의 leftmost는 검색 경로에서 정확히 계산해야 합니다. 삭제 반환 NULL이 삭제 실패라는 뜻은 아니고 새 최소 없음 또는 캐시 변경 없음일 수 있습니다.',
        '네 cached helper와 반환 leftmost의 초기값을 읽으세요.',
        [('cached 삭제의 NULL 반환은 반드시 실패인가?', '아니며 삭제 성공에서도 NULL일 수 있다', '항상 삭제되지 않았다는 뜻이다', '최소가 아닌 항목을 지우거나 마지막 최소를 지우면 NULL을 반환합니다. 반환은 오류 코드가 아니라 새 최소 정보입니다.'),
         ('cached 루트를 일반 rb_erase만으로 바꾸면?', 'rb_leftmost가 오래된 값으로 남을 수 있다', '캐시를 항상 자동으로 찾아 고친다', '일반 루트 API는 별도 rb_leftmost를 모릅니다. 최소 캐시를 유지하는 wrapper 또는 호출자의 정확한 갱신이 필요합니다.')],
        [('O(1)의 비용', '즉시 읽기는 삽입·삭제·교체마다 캐시를 유지하는 비용과 규약으로 얻습니다. 어떤 변경 경로든 빠뜨리면 빠른 읽기가 잘못된 포인터를 반환합니다.'),
         ('대칭 캐시 없음', 'rb_root_cached는 왼쪽 최소만 기본 저장합니다. 최대값 캐시가 필요하면 사용자가 별도 상태와 모든 변경 규칙을 설계해야 합니다.')])

    lesson('레드블랙 add·less 비교로 빈 자리 찾기', 'rb_add_cached',
        '객체 사이의 부울 비교로 삽입 위치를 찾는 공개 helper를 배웁니다.',
        'less(node,parent)가 참이면 왼쪽으로, 거짓이면 오른쪽으로 이동해 빈 연결을 찾습니다. rb_add는 연결과 색 복구를 수행합니다. rb_add_cached는 오른쪽 이동이 있었는지 기록해 새 최소 여부를 계산하고 cached 색 복구를 호출합니다. 동등 키는 삽입 검색에서 오른쪽으로 가지만 회전 후 위치를 고정하지 않습니다.',
        'less는 일관된 엄격한 순서를 정의해야 합니다. 동등 항목도 추가하는 API이므로 유일 키가 필요하면 find_add 등의 중복 검사 흐름을 사용합니다. 반환 node 또는 NULL은 새 최소 여부이며 할당 결과가 아닙니다.',
        '두 add 함수의 공통 검색과 leftmost 변화를 비교하세요.',
        [('less가 동등 키에서 거짓이면 rb_add는?', '오른쪽 빈 경로로 진행해 항목을 추가한다', '기존 동등 항목을 자동 반환하고 삽입을 막는다', 'rb_add에는 동등 판단과 중복 거절 분기가 없습니다. less가 거짓인 경로로 진행하여 새 항목을 추가합니다.'),
         ('균형 회전 뒤 동등 키가 항상 오른쪽에만 있다고 가정해도 되는가?', '안 되며 중위 순서와 비교 계약으로 검색해야 한다', '가능하며 회전은 동등 노드를 절대 이동하지 않는다', '회전은 정렬 순서를 유지하지만 동등 노드의 좌우 배치를 바꿀 수 있습니다. 삽입 검색 경로를 영구 위치 규칙으로 확대하지 않습니다.')],
        [('호출 순서', 'helper가 rb_link_node와 rb_insert_color를 호출하므로 사용자가 다시 색 복구를 중복 호출하지 않습니다.'),
         ('캐시 반환', '빈 트리의 첫 삽입은 새 최소입니다. 중간에 오른쪽 이동이 있었으면 기존 더 앞선 노드가 있어 새 최소가 아닙니다.')])

    lesson('레드블랙 find_add·동등 항목 반환 또는 삽입', 'rb_find_add',
        '키가 이미 있는지 찾는 작업과 없을 때의 삽입을 같은 검색 경로로 처리하는 방법을 배웁니다.',
        '노드 비교 cmp가 음수면 왼쪽, 양수면 오른쪽으로 이동하고 0이면 기존 parent를 반환합니다. 끝까지 동등 항목이 없으면 새 노드를 연결하고 색을 복구한 뒤 NULL을 반환합니다. RCU 형태는 같은 검색 뒤 rb_link_node_rcu로 release 공개하고 같은 색 복구를 호출합니다.',
        '반환 NULL은 새 노드가 삽입되었다는 뜻이고 non-NULL은 기존 동등 노드입니다. 두 writer의 동시 find_add를 이 helper 자체가 직렬화하지 않습니다. 검색과 삽입의 전체 변경 구간을 보호하며 중복으로 반환된 새 객체의 정리는 호출자가 결정합니다.',
        'c==0의 조기 반환과 함수 끝 NULL 반환을 비교하세요.',
        [('find_add가 NULL을 반환했으면 정상 계약에서 무슨 일이 있었는가?', '동등 항목이 없어 새 노드가 삽입되었다', '항상 메모리 할당에 실패했다', '함수에는 할당 실패 반환이 없습니다. 동등하면 기존 노드를, 삽입을 완료하면 NULL을 반환하는 계약입니다.'),
         ('find_add_rcu가 동시 writer 두 개의 중복 삽입을 자동으로 막는가?', '아니며 writer 직렬화가 필요하다', 'RCU 이름만으로 검색·삽입 전체가 원자적이다', 'RCU 형태는 연결 공개 순서를 추가합니다. 두 검색이 동시에 없음을 보고 삽입하는 경쟁을 자체 잠금으로 막지 않습니다.')],
        [('비교 형식', 'find_add의 cmp는 새 rb_node와 기존 const rb_node를 비교합니다. key-first 검색의 void 키 인자 형식과 다릅니다.'),
         ('RCU 회전', 'rcu 연결 뒤의 색 복구 회전까지 하나의 원자적 변경으로 보이는 것은 아닙니다. 동시 독자의 false negative와 수명 규약을 함께 이해합니다.')])

    lesson('레드블랙 key 검색·일반 읽기와 RCU 하강', 'rb_find_rcu',
        '큰 더미 객체를 만들지 않고 검색 키만 전달해 노드를 찾는 방법을 배웁니다.',
        'rb_find는 cmp(key,node)의 부호로 좌우를 선택하고 0이면 현재 노드를 반환합니다. 끝에 도달하면 NULL입니다. rb_find_rcu는 자식 하강에 rcu_dereference_raw를 사용합니다. 키 인자가 따로 있으므로 검색을 위해 전체 자료 객체를 스택에 만들 필요가 없습니다. 동시 회전은 탐색이 존재하는 노드를 놓치게 할 수 있습니다.',
        '삽입과 검색 비교 기준을 일치시킵니다. RCU helper 자체가 읽기 보호 구간이나 객체 참조를 대신 시작하지 않습니다. 반환 포인터를 사용할 때 수명을 보호하고 NULL의 의미를 동시 변경 조건에 맞게 판단합니다.',
        '두 find 함수의 루트 읽기와 자식 읽기 차이를 읽으세요.',
        [('key-first 검색이 별도 키 인자를 사용하는 장점은?', '전체 자료 객체를 더미로 만들 필요가 줄어든다', '어떤 비교 함수도 필요 없어지는 것이다', '소스는 큰 객체를 스택에 만드는 것이 어려울 수 있다는 이유를 설명합니다. 비교 함수는 여전히 키와 노드의 관계를 제공해야 합니다.'),
         ('rb_find_rcu가 자동으로 제공하지 않는 것은?', '반환 객체의 수명 보호와 완전한 동시 스냅샷이다', '자식 포인터를 읽는 하강 동작이다', 'RCU 자식 읽기는 전체 보호 프로토콜을 대체하지 않습니다. 원본은 회전 중 false negative도 명시합니다.')],
        [('루트 관찰', '원본의 초기 root->rb_node 읽기와 자식의 rcu_dereference_raw를 그대로 구분합니다. 이름만 보고 모든 읽기가 같은 매크로라고 설명하지 않습니다.'),
         ('일치 선택', '동등 항목 여러 개 중 일반 rb_find가 어느 것을 반환하는지 보장하지 않습니다. 첫 동등 항목이 필요하면 rb_find_first 계약을 사용합니다.')])

    lesson('레드블랙 동등 키 순회·첫 일치와 연속 그룹', 'rb_find_first',
        '중복 키가 있는 트리에서 첫 일치를 찾아 그 그룹만 순회하는 원리를 배웁니다.',
        'rb_find_first는 비교가 0이면 match를 저장하면서 계속 왼쪽으로 내려가 더 앞선 동등 항목을 찾습니다. 음수도 왼쪽, 양수는 오른쪽입니다. rb_next_match는 중위 다음 노드를 얻어 키가 다르면 NULL로 바꿉니다. rb_for_each는 이 두 helper를 연결해 동등 키 그룹을 순회합니다.',
        '트리의 전체 순서와 키 비교가 맞아 동등 그룹이 연속해야 합니다. next_match에 마지막 NULL을 다시 전달하지 않고 반복 조건으로 끝을 처리합니다. 순회 중 키·구조 변경은 기존 이웃 관계를 깨뜨릴 수 있어 보호해야 합니다.',
        'c<=0의 match 갱신과 왼쪽 하강, rb_next_match의 비교를 읽으세요.',
        [('find_first가 동등 항목을 찾고도 왼쪽으로 계속 가는 이유는?', '더 앞선 동등 항목이 있을 수 있기 때문이다', '찾은 모든 항목을 삭제하기 위해서다', '동등 항목이 여러 개일 수 있습니다. 일치를 기억하고 왼쪽 탐색을 계속해 중위 순서의 첫 일치를 구합니다.'),
         ('next_match의 다음 노드가 다른 키이면?', 'NULL로 그룹 순회를 끝낸다', '다른 키도 무조건 같은 그룹으로 반환한다', '중위 순서에서 동등 그룹은 연속이라는 비교 계약을 이용합니다. 다음 노드가 다르면 해당 키의 연속 그룹이 끝났습니다.')],
        [('일반 find와 차이', '일반 find는 첫 만난 동등 노드에서 끝납니다. find_first는 가장 앞선 동등 노드를 위해 왼쪽 탐색을 계속합니다.'),
         ('순회 비용', '첫 일치를 찾는 높이 비용과 일치 그룹을 방문하는 비용을 구분합니다. 일치하지 않는 전체 트리를 매번 선형 검색하는 방식이 아닙니다.')])

    lesson('레드블랙 비교 인터페이스·세 호출 형식과 순서 계약', 'rb_find',
        '비슷한 이름의 검색·삽입 함수가 서로 다른 비교 형식을 쓰는 이유를 배웁니다.',
        'less(a,b)는 노드 두 개의 부울 순서를, cmp(node,parent)는 노드 두 개의 부호 결과를, cmp(key,node)는 별도 키와 노드의 부호 결과를 제공합니다. comp(a의 키,b)<0은 less(a,b), >0은 less(b,a), 동등은 양쪽 less가 모두 거짓인 관계에 연결됩니다. 세 형식은 같은 정렬 관계를 표현해야 합니다.',
        '자료의 필드·형식에 맞는 콜백을 선언하고 인자 순서를 바꾸지 않습니다. 부분 순서로 여러 항목이 동등할 수 있으면 일반 find의 선택을 특정 객체로 고정하지 않습니다. 공개 헤더의 기본·RCU·캐시·후위 API를 목적에 맞게 연결합니다.',
        'helper 앞 세 호출 관례 설명과 함수 포인터 선언을 비교하세요.',
        [('less(a,b)와 less(b,a)가 모두 거짓이면 이 비교 관계에서는?', '두 항목이 동등하다', '반드시 두 포인터가 같은 주소다', '동등성은 정의한 키·순서 관계에 관한 것입니다. 서로 다른 객체도 같은 키이거나 비교가 구분하지 않는 항목일 수 있습니다.'),
         ('삽입은 key 오름차순인데 검색 비교는 주소 순서이면?', '탐색 경로가 틀려 결과를 놓칠 수 있다', '트리가 자동으로 두 기준을 동시에 정렬한다', '자식 방향은 삽입 기준으로 구성되어 있습니다. 다른 기준의 부호로 하강하면 찾을 키가 있는 가지를 버릴 수 있습니다.')],
        [('선언 범위', '헤더는 기본 색 복구·삭제, 중위·후위 순회와 두 교체 함수의 외부 선언도 제공합니다. 선언은 구현 전체가 아니므로 lib/rbtree.c와 확장 헤더를 함께 읽습니다.'),
         ('동시성 책임', '이 header helper들에 일반 mutex 잠금이 자동으로 추가되지 않습니다. writer 직렬화, 독자의 관찰 범위와 해제 규약은 사용하는 자료구조가 설계해야 합니다.')])
